html.dark [data-workspace-area="conversation"] {
  isolation: isolate;
}

html.dark [data-workspace-area="conversation"]::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image: var(--theme-background-image, none);
  background-repeat: no-repeat;
  background-size: clamp(480px, 68%, 820px) auto;
  background-position: center calc(100% + clamp(115px, 23vh, 205px));
  image-rendering: pixelated;
  opacity: .46;
  transition: opacity 180ms ease, background-size 180ms ease, background-position 180ms ease;
}

html.dark :is([data-chat-canvas], [data-chat-column]):has([data-chat-composer-overlay="true"].items-center:not([inert]))
  [data-workspace-area="conversation"]::before {
  background-size: clamp(660px, 106%, 1280px) auto;
  background-position: center 53%;
  opacity: 1;
}

html.dark [data-workspace-area="conversation"] > .bg-background {
  background-color: transparent !important;
}

/* Use the native shell's existing glass, including its attached states. */
html.dark [data-chat-composer-overlay="true"] [data-slot="composer-shell"] {
  --glass-opacity: 39% !important;
  --glass-blur: 22px !important;
  --glass-saturation: 1.35 !important;
  --chat-composer-outline: color-mix(in srgb, var(--foreground, #ebeef4) 14%, transparent) !important;
}

html.dark [data-chat-composer-overlay="true"] [data-slot="composer-shell"]:focus-within {
  --chat-composer-outline: color-mix(in srgb, var(--ring, #7da2ff) 42%, transparent) !important;
}

html.dark [data-chat-composer-overlay="true"] [data-chat-composer-surface="true"]:not([data-slot="composer-shell"] *) {
  background-color: color-mix(in srgb, var(--card, #171920) 48%, transparent);
  backdrop-filter: blur(22px) saturate(1.35);
  border-color: color-mix(in srgb, var(--foreground, #ebeef4) 14%, transparent);
}

/* T3 exposes these two live statuses in its accessible sidebar row label. */
html.dark [data-thread-item] [data-sidebar-row]:is(
  [aria-label$=", Approval"], [aria-label*=", Approval, "],
  [aria-label$=", Input"], [aria-label*=", Input, "]
) {
  box-shadow: inset 2px 0 0 #efba60;
}

@media (prefers-reduced-motion: reduce) {
  html.dark [data-workspace-area="conversation"]::before {
    transition: none;
  }
}

@media (prefers-contrast: more), (prefers-reduced-transparency: reduce) {
  html.dark [data-workspace-area="conversation"]::before {
    display: none;
  }

  html.dark [data-chat-composer-overlay="true"] [data-slot="composer-shell"] {
    --glass-opacity: 96% !important;
  }

  html.dark [data-chat-composer-overlay="true"] [data-chat-composer-surface="true"]:not([data-slot="composer-shell"] *) {
    background-color: var(--card, #171920);
  }
}

@media (forced-colors: active) {
  html.dark [data-workspace-area="conversation"]::before {
    display: none;
  }
}

[data-thread-details-card]{background:rgba(11,17,32,0.88) !important;backdrop-filter:blur(20px) saturate(1.3);-webkit-backdrop-filter:blur(20px) saturate(1.3);border:1px solid rgba(255,255,255,.09) !important;border-radius:16px !important;box-shadow:0 20px 50px -20px rgba(0,0,0,.9) !important;}

/* ---------- Title-first thread rows ----------
   T3's card row has up to three lines: project + status, title, and a meta
   line (branch, worktree or environment, then T3's icons). With "Title first"
   on, a grid re-flows them without moving anything in the DOM:
     title ............................ status/time
     [icon][pin] project · meta line .... icons
   The first two lines become display: contents so their children land in the
   grid; the meta line stays one flex item (its own leading icon, label and
   icons keep T3's layout), so every meta-line shape works. Hover widens only
   the status cell: the second line never moves. Bot rows keep their layout. */
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) {
  display: grid !important;
  /* icon | pin (empty when unpinned) | project | meta line | status */
  grid-template-columns: auto auto minmax(0, max-content) minmax(0, 1fr) auto;
  grid-template-rows: 1.25rem 1.25rem;
  row-gap: 0.125rem;
  align-items: center;
  height: auto !important;
}
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > :is(.h-5, .mt-1) {
  display: contents !important;
}
/* Line 1: the title, then T3's status slot (time, or Snooze/Settle on hover). */
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > .mt-1 > [dir] {
  grid-area: 1 / 1 / 2 / 5;
}
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > .h-5 > .group\/sidebar-status-slot {
  grid-area: 1 / 5;
  justify-self: end;
  margin-left: 0.375rem;
}
/* Line 2: project icon and name... */
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > .h-5 > :first-child:not(.truncate, .group\/sidebar-status-slot) {
  grid-area: 2 / 5;
  justify-self: end;
  margin-left: 0.375rem;
}
/* A pinned row's pin sits after the project icon (in T3 it is line 1's second child). */
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > .h-5 > :nth-child(2):not(.truncate, .group\/sidebar-status-slot) {
  grid-area: 2 / 1;
  margin-right: 0.25rem;
}
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > .h-5 > .truncate {
  display: none !important;
}
/* ...then the meta line as one piece, after a dot. */
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > .mt-0\.5 {
  grid-area: 2 / 2 / 3 / 5;
  min-width: 0;
  margin-top: 0 !important;
}
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > .mt-0\.5::before {
  content: none;
  flex: none;
  margin-left: 0.25rem;
}
/* Rows without a meta line: T3's icons sit at the end of line 2. */
html.dark [data-thread-item] [data-sidebar-row][role="button"] > .relative.z-10:has(> .h-5 > .group\/sidebar-status-slot):has(> .mt-1 > [dir]) > .mt-1 > :not([dir]) {
  grid-area: 2 / 2 / 3 / 5;
  justify-self: end;
}

/* mock-match */
html.dark [data-thread-item] .relative.z-10>.mt-0\.5>.ml-auto[aria-hidden],html.dark [data-thread-item] .relative.z-10>.mt-1>span[aria-hidden]{display:none!important}
html.dark [data-thread-item] .relative.z-10>.mt-1>[dir]{font-weight:500}
html.dark [data-thread-item] [aria-current=page] .relative.z-10>.mt-1>[dir]{font-weight:600;color:var(--foreground)}
/* mock-match end */
